  <div class="dashboard-cards sites-cards"><div class="card metric-card"><div><div class="metric-title">Money in</div><strong class="metric-value">${ksh(d.totals.inMinor)}</strong><p>Payments and installation fees</p></div></div><div class="card metric-card"><div><div class="metric-title">Reversed</div><strong class="metric-value">${ksh(d.totals.reversedMinor)}</strong><p>Payments undone</p></div></div><div class="card metric-card"><div><div class="metric-title">Paid out</div><strong class="metric-value">${ksh(d.totals.outMinor)}</strong><p>Refunds and withdrawals</p></div></div><div class="card metric-card"><div><div class="metric-title">Net</div><strong class="metric-value">${ksh(d.totals.netMinor)}</strong><p>In − reversed − paid out</p></div></div></div>
