  const badge=st=>`<span class="status ${st==='issued'?'online':st==='rejected'?'offline':'warning'}">${H(st)}</span>`;
  $('#im-body').innerHTML=`<section class="card sites-panel"><div class="card-header"><div><h2>Requests</h2></div></div>${table(['WHEN','ITEM','QTY','FOR','BY','STATUS',''],d.requests,r=>`<tr><td>${H(stamp(r.requestedAt))}</td><td>${H(r.itemName)}</td><td>${r.quantity}</td><td class="muted">${H(r.reason)}</td><td>${H(r.requestedBy||'')}</td><td>${badge(r.status)}${r.cost!=null?`<small>${ksh(r.cost)}</small>`:''}${r.note?`<small>${H(r.note)}</small>`:''}</td><td>${boss?(r.status==='requested'?`<button class="button primary" data-sr="approve" data-id="${r.id}">Approve</button> <button class="button secondary" data-sr="reject" data-id="${r.id}">Reject</button>`:r.status==='approved'?`<button class="button primary" data-sr="issue" data-id="${r.id}">Issue</button>`:''):''}</td></tr>`,'No requests yet.')}</section>
  <section class="card sites-panel"><div class="card-header"><div><h2>In stock</h2><p>Value is the cost of what is left, oldest receipts used first.</p></div></div>${table(['ITEM','ON HAND','VALUE',''],d.items,x=>`<tr><td>${H(x.name)}${x.low?' <span class="status warning">Low</span>':''}</td><td>${x.onHand} ${H(x.unit)}</td><td>${ksh(x.value)}</td><td>${boss?`<button class="button secondary" data-sr-rcv="${x.id}">Receive</button>`:''}</td></tr>`,'No stock items. Add them under Fibre → Stock.')}</section>`;
  for(const b of document.querySelectorAll('[data-sr]'))b.onclick=async()=>{let note='';if(b.dataset.sr==='reject'){note=prompt('Why reject?');if(note===null)return;}try{await api('stock-requests/'+b.dataset.id+'/'+b.dataset.sr,'POST',{note});toast('Done');pages.stockRequests(id);}catch(e){toast(e.message);}};
